package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var DateRecData DateRec
var dateFile *os.File
var dateScanner *bufio.Scanner

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func truncToDigits(v int64, digits int) int64 {
	m := pow10(digits)
	return v % m
}

func parsePic9(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var v int64 = 0
	for _, c := range t {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			return 0
		}
	}
	return v
}

func formatPic9(v int64, width int) string {
	if v < 0 {
		s := fmt.Sprintf("%0*d", width, v)
		if len(s) > width {
			s = s[len(s)-width:]
		}
		return s
	}
	m := pow10(width)
	tv := v % m
	return fmt.Sprintf("%0*d", width, tv)
}

func MainPara() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	dateScanner = bufio.NewScanner(dateFile)
	ReadPara()
	for !(WsEofFlag == "Y") {
		ProcessPara()
	}
	dateFile.Close()
	out := "VALID: " + formatPic9(WsValid, 2) + " BAD MONTH: " + formatPic9(WsBadMonth, 2) + " BAD DAY: " + formatPic9(WsBadDay, 2)
	os.Stdout.WriteString(out + "\n")
}

func ReadPara() {
	if dateScanner.Scan() {
		line := dateScanner.Text()
		recStr := line
		if len(recStr) < 12 {
			recStr = recStr + strings.Repeat(" ", 12-len(recStr))
		} else if len(recStr) > 12 {
			recStr = recStr[:12]
		}
		DateRecData.DtId = recStr[0:4]
		DateRecData.DtYyyy = parsePic9(recStr[4:8])
		DateRecData.DtMm = parsePic9(recStr[8:10])
		DateRecData.DtDd = parsePic9(recStr[10:12])
	} else {
		if err := dateScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	LeapPara()
	if DateRecData.DtMm < 1 || DateRecData.DtMm > 12 {
		WsBadMonth = truncToDigits(WsBadMonth+1, 2)
		s := DateRecData.DtId + " BAD MONTH " + formatPic9(DateRecData.DtMm, 2)
		os.Stdout.WriteString(s + "\n")
	} else {
		DaysPara()
		if DateRecData.DtDd < 1 || DateRecData.DtDd > WsMaxDay {
			WsBadDay = truncToDigits(WsBadDay+1, 2)
			s := DateRecData.DtId + " BAD DAY " + formatPic9(DateRecData.DtDd, 2) + " MAX " + formatPic9(WsMaxDay, 2)
			os.Stdout.WriteString(s + "\n")
		} else {
			WsValid = truncToDigits(WsValid+1, 2)
			s := DateRecData.DtId + " VALID " + formatPic9(DateRecData.DtYyyy, 4) + "-" + formatPic9(DateRecData.DtMm, 2) + "-" + formatPic9(DateRecData.DtDd, 2)
			os.Stdout.WriteString(s + "\n")
		}
	}
	ReadPara()
}

func LeapPara() {
	q := DateRecData.DtYyyy / 4
	r := DateRecData.DtYyyy % 4
	WsQ = truncToDigits(q, 4)
	WsR4 = truncToDigits(r, 3)
	q = DateRecData.DtYyyy / 100
	r = DateRecData.DtYyyy % 100
	WsQ = truncToDigits(q, 4)
	WsR100 = truncToDigits(r, 3)
	q = DateRecData.DtYyyy / 400
	r = DateRecData.DtYyyy % 400
	WsQ = truncToDigits(q, 4)
	WsR400 = truncToDigits(r, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	if DateRecData.DtMm == 2 {
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	} else if DateRecData.DtMm == 4 || DateRecData.DtMm == 6 || DateRecData.DtMm == 9 || DateRecData.DtMm == 11 {
		WsMaxDay = 30
	} else {
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
}
